// Normalizar burbujas — guardrail determinístico entre el formatter y ManyChat.
// Cierra H6 (una sola pregunta) y P1 (repetición del nombre) sin depender del LLM,
// y arma el body de ManyChat de forma segura (hoy `Settear variables` lo concatena
// como string y borra TODAS las comillas del mensaje del agente).

const content = $json.message?.content ?? $json;
const subscriberId = $('Webhook').first().json.body.id;

// Nombre del lead: se usa para detectar repetición. Si no lo tenemos, no se toca nada.
let nombre = '';
try {
  const lead = $('Buscar si ya existe').first().json;
  nombre = String(lead?.Nombre || '').trim().split(' ')[0];
} catch (e) { nombre = ''; }

const partes = [content.parte1, content.parte2, content.parte3]
  .map(p => (p == null ? '' : String(p)))
  .map(p => p.replace(/\*/g, '').trim());

// ── H6 · una sola pregunta en todo el mensaje ────────────────────────────────
// Se conserva la PRIMERA oración interrogativa y se descartan las siguientes.
// Motivo: la última pregunta suele ser la que el flujo quiere, pero la primera es
// la que el lead lee antes de responder — dos preguntas bajan la tasa de respuesta.
let vistas = 0;
const sinExtras = partes.map(parte => {
  if (!parte) return '';
  // corta en oraciones conservando el signo de cierre
  const oraciones = parte.match(/[^.!?]+[.!?]*/g) || [parte];
  const out = [];
  for (const o of oraciones) {
    if (o.includes('?')) {
      vistas++;
      if (vistas > 1) continue; // se descarta la pregunta sobrante
    }
    out.push(o);
  }
  return out.join('').replace(/\s+/g, ' ').trim();
});

// ── P1 · el nombre del lead aparece como mucho una vez ───────────────────────
let nombreUsado = 0;
const sinRepetirNombre = sinExtras.map(parte => {
  if (!parte || !nombre || nombre.length < 3) return parte;
  const re = new RegExp(`\\b${nombre.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'gi');
  return parte.replace(re, (m) => {
    nombreUsado++;
    if (nombreUsado === 1) return m;
    return '';                       // se quita la repetición
  })
   .replace(/\s+([,.!?])/g, '$1')      // espacio huérfano antes de un signo
   .replace(/,\s*([.!?])/g, '$1')      // coma pegada a un signo de cierre: "Te sirve,?" -> "Te sirve?"
   .replace(/\s*,\s*,/g, ',')          // comas dobles
   .replace(/\s{2,}/g, ' ')
   .replace(/^[\s,]+/, '')             // coma o espacio al inicio
   .replace(/[\s,]+$/, '')             // coma o espacio al final
   .trim();
});

// Si al quitar el nombre la frase quedó empezando en minúscula, se restituye la mayúscula.
const finales = sinRepetirNombre
  .map(p => (p ? p.charAt(0).toUpperCase() + p.slice(1) : p))
  .filter(p => p && p.length > 0);
if (finales.length === 0) {
  throw new Error('Normalizar burbujas: quedaron 0 partes con contenido');
}

// ── Body seguro: objeto real, no concatenación de strings ───────────────────
const mcBody = {
  subscriber_id: subscriberId,
  fields: finales.map((valor, i) => ({ field_name: `parte${i + 1}`, field_value: valor })),
};

return [{ json: {
  mcBody,
  preguntas: Math.min(vistas, 1),
  partes_emitidas: finales.length,
  texto_completo: finales.join('\n\n'),
}}];
